4.2. How to use this light information in our crash analysis
We can use it in two ways:

As an exposure denominator: crashes per unit of light. Residents show where people sleep. Light shows where activity happens: the CBD, the airport, the N2 corridor and Bellville.
As a covariate in the model (log(ntl_mean)), as an activity proxy alongside other variables.

But also, we need to keep in mind that light is not the same as people. Densely populated areas such as Khayelitsha and Mitchells Plain (south-east, near False Bay) are less bright than their population would suggest, while the airport and port are very bright with almost no residents.
In order to achieve this, we will create a function called summarise_zones() function that would give two numbers per ward:

ntl_mean: average brightness, meaning how intensely lit the ward is.
ntl_sum: total light, meaning the overall amount of activity. It grows with ward size.

We will first read in the cached .tif, so save ntl_city_2023 as data/cache/ntl_city_2023.tif first.

dir.create("data/cache", recursive = TRUE, showWarnings = FALSE)
terra::writeRaster(ntl_tazs_2023, "data/cache/ntl_tazs_2023.tif", overwrite = TRUE)
ntl &lt;- terra::rast(file.path(cache_dir, "ntl_tazs_2023.tif"))
terra::hasValues(ntl)   # should be TRUE

[1] TRUE



summarise_zones &lt;- function(zones) {

  zones &lt;- zones |&gt;
    st_transform(32734) |&gt;
    mutate(.zid = row_number())

  crashes_proj &lt;- police_crashes_sf |&gt;
    st_transform(st_crs(zones)) |&gt;
    filter(!st_is_empty(geometry))

  crash_summary &lt;- police_crashes_sf |&gt;
  sf::st_drop_geometry() |&gt;
  group_by(COMPNT_NM, month_year) |&gt;
  summarise(
    fatalsum = sum(imp.fatalsum, na.rm = TRUE),
    serioussum = sum(imp.serioussum, na.rm = TRUE),
    slightsum = sum(imp.slightsum, na.rm = TRUE),
    noinjurysum = sum(imp.noinjurysum, na.rm = TRUE),
    totalsum = sum(imp.totalsum, na.rm = TRUE),
    .groups = "drop"
  )

  # 2. Road length
  roads_proj &lt;- road_network |&gt;
    st_transform(st_crs(zones))

  rl &lt;- st_intersection(
    roads_proj,
    zones |&gt; select(COMPNT_NM)
  ) |&gt;
    mutate(
      km = as.numeric(st_length(geometry)) / 1000
    ) |&gt;
    st_drop_geometry() |&gt;
    group_by(COMPNT_NM) |&gt;
    summarise(
      road_km = sum(km, na.rm = TRUE),
      .groups = "drop"
    )

  # 3. Nighttime lights
  ex &lt;- terra::extract(
    ntl,
    terra::vect(st_transform(zones, terra::crs(ntl))),
    exact = TRUE
  )

  names(ex)[2] &lt;- "val"

  nl &lt;- ex |&gt;
    filter(!is.na(val)) |&gt;
    group_by(.zid = ID) |&gt;
    summarise(
      ntl_mean = weighted.mean(val, fraction),
      ntl_sum = sum(val * fraction),
      .groups = "drop"
    )

  # 4. Combine everything
  zones |&gt;
    mutate(
      area_km2 = as.numeric(st_area(geometry)) / 1e6
    ) |&gt;
    left_join(crash_summary, by = "COMPNT_NM") |&gt;
    left_join(rl, by = "COMPNT_NM") |&gt;
    left_join(nl, by = ".zid") |&gt;
    mutate(
      road_km = coalesce(road_km, 0)
    ) 
}

taz_df &lt;- summarise_zones(policestations_zones_cpt)

Points, lines and rasters can be re-aggregated to any zones. Census and tax tables cannot.

4.3. Merge taz_df with the population data

Extract the unique TAZ polygons


taz_unique &lt;- taz_df |&gt; 
  select(COMPNT_NM)|&gt;
  unique()


Calculate the intersection with wards


taz_ward_intersection &lt;- st_intersection(
  taz_unique |&gt; select(COMPNT_NM),
  wards_cpt |&gt; select(WardNo)
)


taz_ward_intersection &lt;- taz_ward_intersection |&gt;
  mutate(
    overlap_km2 = as.numeric(st_area(geometry)) / 1e6
  ) |&gt;
  left_join(
    wards_cpt |&gt;
      st_drop_geometry() |&gt;
      select(WardNo, ward_area_km2 = area_km2),
    by = "WardNo"
  ) |&gt;
  mutate(
    weight = overlap_km2 / ward_area_km2
  )


Calculate the population per TAZ


taz_summary &lt;- taz_ward_intersection |&gt;
  st_drop_geometry() |&gt;
  left_join(
    wards_cpt |&gt;
      st_drop_geometry() |&gt;
      transmute(
        WardNo,
        population = parse_number(as.character(Total))
      ),
    by = "WardNo"
  ) |&gt;
  group_by(COMPNT_NM) |&gt;
  summarise(
    population = sum(population * weight, na.rm = TRUE),
    .groups = "drop"
  )

Add this information to our taz_df

taz_df &lt;- taz_df |&gt; left_join(
  taz_summary, by = "COMPNT_NM"
)
